CREATE TABLE businesses(id TEXT PRIMARY KEY,settings TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 0,delivery_hold INTEGER NOT NULL DEFAULT 0,link_key TEXT NOT NULL);
CREATE TABLE tenant_domains(hostname TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),canonical_origin TEXT NOT NULL);
CREATE TABLE mutation_guards(id TEXT PRIMARY KEY,ok INTEGER NOT NULL CHECK(ok=1));
CREATE TABLE services(id TEXT NOT NULL,business_id TEXT NOT NULL REFERENCES businesses(id),version INTEGER NOT NULL DEFAULT 1,data TEXT NOT NULL,PRIMARY KEY(business_id,id));
CREATE TABLE customers(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),data TEXT NOT NULL,UNIQUE(business_id,id));
CREATE TABLE vehicles(id TEXT PRIMARY KEY,business_id TEXT NOT NULL,customer_id TEXT NOT NULL,data TEXT NOT NULL,UNIQUE(business_id,id),FOREIGN KEY(business_id,customer_id) REFERENCES customers(business_id,id));
CREATE TABLE bookings(id TEXT PRIMARY KEY,business_id TEXT NOT NULL,customer_id TEXT NOT NULL,vehicle_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,status TEXT NOT NULL,start_ms INTEGER NOT NULL,end_ms INTEGER,buffer_minutes INTEGER NOT NULL DEFAULT 0,snapshot TEXT NOT NULL,data TEXT NOT NULL,access_hash TEXT NOT NULL,access_expires INTEGER NOT NULL,proposal TEXT,version INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,UNIQUE(business_id,id),UNIQUE(business_id,idempotency_key),FOREIGN KEY(business_id,customer_id) REFERENCES customers(business_id,id),FOREIGN KEY(business_id,vehicle_id) REFERENCES vehicles(business_id,id));
CREATE INDEX booking_schedule ON bookings(business_id,status,start_ms,end_ms);
CREATE TABLE history(id TEXT PRIMARY KEY,business_id TEXT NOT NULL,booking_id TEXT NOT NULL,actor TEXT NOT NULL,event TEXT NOT NULL,data TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(business_id,id),FOREIGN KEY(business_id,booking_id) REFERENCES bookings(business_id,id));
CREATE TABLE notifications(id TEXT PRIMARY KEY,business_id TEXT NOT NULL,booking_id TEXT NOT NULL,event TEXT NOT NULL,read_at INTEGER,created_at INTEGER NOT NULL,UNIQUE(business_id,id),FOREIGN KEY(business_id,booking_id) REFERENCES bookings(business_id,id));
CREATE TABLE owners(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),email TEXT NOT NULL,password_hash TEXT NOT NULL,UNIQUE(business_id,email),UNIQUE(business_id,id));
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,business_id TEXT NOT NULL,owner_id TEXT NOT NULL,expires INTEGER NOT NULL,FOREIGN KEY(business_id,owner_id) REFERENCES owners(business_id,id));
CREATE TABLE subscriptions(id TEXT PRIMARY KEY,business_id TEXT NOT NULL,endpoint TEXT NOT NULL,data TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,owner_id TEXT NOT NULL,registered_at INTEGER NOT NULL,last_seen INTEGER NOT NULL,expires_at INTEGER,key_fingerprint TEXT NOT NULL,UNIQUE(business_id,endpoint),FOREIGN KEY(business_id,owner_id) REFERENCES owners(business_id,id));
CREATE TABLE deliveries(id TEXT PRIMARY KEY,business_id TEXT NOT NULL,notification_id TEXT NOT NULL,channel TEXT NOT NULL,target TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',attempts INTEGER NOT NULL DEFAULT 0,next_attempt INTEGER NOT NULL DEFAULT 0,last_error TEXT,provider_id TEXT,payload TEXT NOT NULL,claimed_until INTEGER NOT NULL DEFAULT 0,claim_token TEXT,UNIQUE(notification_id,channel,target),FOREIGN KEY(business_id,notification_id) REFERENCES notifications(business_id,id));
CREATE TABLE delivery_attempts(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),delivery_id TEXT NOT NULL REFERENCES deliveries(id),attempt INTEGER NOT NULL,status TEXT NOT NULL,error TEXT,created_at INTEGER NOT NULL);
CREATE TABLE webhook_receipts(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),provider_id TEXT NOT NULL,type TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE worker_errors(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),message TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE schedule_blocks(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),start_ms INTEGER NOT NULL,end_ms INTEGER NOT NULL,label TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE jobs(id TEXT PRIMARY KEY,business_id TEXT NOT NULL,booking_id TEXT NOT NULL,customer_id TEXT NOT NULL,vehicle_id TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(business_id,id),UNIQUE(business_id,booking_id),FOREIGN KEY(business_id,booking_id) REFERENCES bookings(business_id,id),FOREIGN KEY(business_id,customer_id) REFERENCES customers(business_id,id),FOREIGN KEY(business_id,vehicle_id) REFERENCES vehicles(business_id,id));
CREATE TABLE media(id TEXT PRIMARY KEY,business_id TEXT NOT NULL,booking_id TEXT NOT NULL,customer_id TEXT NOT NULL,vehicle_id TEXT NOT NULL,job_id TEXT,kind TEXT NOT NULL CHECK(kind IN ('intake','before','after')),filename TEXT NOT NULL,original_mime TEXT NOT NULL,original_key TEXT NOT NULL,preview_key TEXT NOT NULL,sha256 TEXT NOT NULL,original_bytes INTEGER NOT NULL,preview_bytes INTEGER NOT NULL,include_on_invoice INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,UNIQUE(business_id,id),UNIQUE(booking_id,sha256,kind),FOREIGN KEY(business_id,booking_id) REFERENCES bookings(business_id,id),FOREIGN KEY(business_id,customer_id) REFERENCES customers(business_id,id),FOREIGN KEY(business_id,vehicle_id) REFERENCES vehicles(business_id,id),FOREIGN KEY(business_id,job_id) REFERENCES jobs(business_id,id));
CREATE TABLE website_photos(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),slot TEXT NOT NULL,alt TEXT NOT NULL,caption TEXT NOT NULL,rights_note TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',original_mime TEXT NOT NULL,original_key TEXT NOT NULL,preview_key TEXT NOT NULL,sha256 TEXT NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(business_id,slot));
CREATE TABLE reviews(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),booking_id TEXT,display_name TEXT NOT NULL,rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),feedback TEXT NOT NULL,consent INTEGER NOT NULL,idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',version INTEGER NOT NULL DEFAULT 1,moderation_reason TEXT,moderated_at INTEGER,created_at INTEGER NOT NULL,UNIQUE(business_id,idempotency_key),FOREIGN KEY(business_id,booking_id) REFERENCES bookings(business_id,id));
CREATE TABLE review_moderation(id TEXT PRIMARY KEY,review_id TEXT NOT NULL REFERENCES reviews(id),owner_id TEXT NOT NULL REFERENCES owners(id),from_status TEXT NOT NULL,to_status TEXT NOT NULL,reason TEXT,created_at INTEGER NOT NULL);
CREATE TABLE audit_events(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),actor_id TEXT NOT NULL,event TEXT NOT NULL,record_id TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE backup_runs(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),started_at INTEGER NOT NULL,finished_at INTEGER,status TEXT NOT NULL,directory TEXT,error TEXT);
